#include "subqcd.hpp"

#include <complex>
#include <FArray.hpp>
#include <constants_mod.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace constants_mod;
using namespace mxpart_mod;
using namespace sprods_com_mod;

//*******************************************************************
//     the matrix elements of the
//     helicity amplitudes for the QCD process
//     q(-p1)+qbar(-p2) --> l(p3)+abar(p4)+g(p5)+g(p6)
//     multiplied by ((a+l)^2-M**2)/(a+l)^2/g^4
//     one colour ordering only
//     left-on quark line only
//*******************************************************************
void subqcd(int i1, int i2, int i3, int i4, int i5, int i6,
            FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
            FArray2D<std::complex<double>>& amp) {
  double s156, s56, s256, s34;

  // begin statement functions
  auto zba2 = [&za, &zb](int k1, int k2, int k3, int k4) {
    return zb(k1,k2)*za(k2,k4) + zb(k1,k3)*za(k3,k4);
  };
  auto zba3 = [&za, &zb](int k1, int k2, int k3, int k4, int k5) {
    return zb(k1,k2)*za(k2,k5) + zb(k1,k3)*za(k3,k5) + zb(k1,k4)*za(k4,k5);
  };
  // end statement functions

  s156 = s(i1,i5) + s(i1,i6) + s(i5,i6);
  s256 = s(i2,i5) + s(i2,i6) + s(i5,i6);
  s56 = s(i5,i6);
  s34 = s(i3,i4);
  (void)s56; (void)s34;

  amp(-1,-1) = -four/s(i3,i4)*zb(i1,i4)*zba3(i1,i2,i6,i5,i3)/zb(i1,i5)/zb(i2,i6)/zb(i6,i5);   // @coverage-probe
  amp(+1,+1) = +four/s(i3,i4)
    *za(i2,i3)*zba3(i4,i1,i6,i5,i2)/za(i1,i5)/za(i2,i6)/za(i6,i5);
  amp(+1,-1) = four/(s(i3,i4)*s(i5,i6))
    *(zba2(i4,i1,i5,i6)*zba2(i5,i2,i6,i3)/za(i1,i5)/zb(i2,i6)
      -za(i1,i6)*za(i2,i3)*zb(i1,i5)*zba2(i4,i1,i5,i6)/za(i1,i5)/s156
      -za(i2,i6)*zb(i1,i4)*zb(i2,i5)*zba2(i5,i2,i6,i3)/zb(i2,i6)/s256);
  amp(-1,+1) = four/(s(i3,i4)*s(i5,i6))
    *(za(i2,i3)*za(i2,i5)*zb(i1,i4)*zb(i1,i6)/za(i2,i6)/zb(i1,i5)
      -za(i2,i3)*std::pow(zb(i1,i6),2)*zba2(i4,i1,i6,i5)/zb(i1,i5)/s156
      -std::pow(za(i2,i5),2)*zb(i1,i4)*zba2(i6,i2,i5,i3)/za(i2,i6)/s256);

  return;
}

extern "C" {
  void subqcd_wrapper(int i1, int i2, int i3, int i4, int i5, int i6,
                      std::complex<double>* fza, std::complex<double>* fzb,
                      std::complex<double>* famp) {

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    FArray2D<std::complex<double>> amp(famp, 3, 3, -1, -1);
    subqcd(i1, i2, i3, i4, i5, i6, za, zb, amp);
  }
}
