    return za(m1,m2)*zb(m2,m4) + za(m1,m3)*zb(m3,m4);
  };
  auto funcpp2 = [&za, &zb, &zab2](int m1, int m2, int m3, int m4, int m5, int m6) {
    return -half*(
      +za(m1,m3)*za(m2,m5)*za(m3,m4)*zb(m4,m2)*zb(m4,m3)*zb(m6,m1)
      +za(m1,m3)*za(m1,m5)*za(m2,m3)*zb(m2,m1)*zb(m4,m3)*zb(m6,m1)
      -za(m1,m2)*za(m3,m4)*za(m3,m5)*zb(m4,m2)*zb(m4,m3)*zb(m6,m1)
