      -4.0*std::pow(za(m1,m5)*za(m2,m3),2)*zb(m2,m1)*zb(m4,m3)*zb(m6,m5)
        /za(m1,m2)
      -za(m1,m3)*za(m2,m5)*za(m3,m5)*zb(m2,m1)*zb(m4,m3)*zb(m6,m5)
      +za(m1,m2)*std::pow(za(m3,m5),2)*zb(m2,m1)*zb(m4,m3)*zb(m6,m5))
      /(std::pow(za(m1,m2),2)*s(m3,m4)*s(m5,m6));
