//---This is the curly braces expression in Eq.(11.6) subject to flip_3
//---ie  flip3:( 1<-->5, 2<-->6, 3<-->4, za<-->zb)
static std::complex<double> Brackpma(int j1, int j2, int j3, int j4, int j5, int j6,
                                     FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  double IDelta;

  // statement functions
  auto t = [](int k1, int k2, int k3) { return s(k1,k2) + s(k2,k3) + s(k3,k1); };
  auto delta = [](int k1, int k2, int k3, int k4, int k5, int k6) { return s(k1,k2) - s(k3,k4) - s(k5,k6); };
  auto zab2 = [&za, &zb](int k1, int k2, int k3, int k4) { return za(k1,k2)*zb(k2,k4) + za(k1,k3)*zb(k3,k4); };

  IDelta = 1.0/(std::pow(s(j1,j2),2) + std::pow(s(j3,j4),2) + std::pow(s(j5,j6),2)
    -2.0*(s(j1,j2)*s(j3,j4) + s(j1,j2)*s(j5,j6) + s(j5,j6)*s(j3,j4)));

  return
    2.0*zb(j1,j2)*za(j2,j3)*zb(j3,j6)
    /zb(j5,j6)/std::pow(zab2(j3,j1,j2,j4),2)
    *(zab2(j3,j1,j2,j6)*zab2(j2,j1,j3,j4)/zab2(j3,j1,j2,j4)
    *L0(-t(j1,j2,j3),-s(j1,j2))/s(j1,j2)
    -za(j2,j3)*zb(j3,j6)
    *(L0(-t(j1,j2,j3),-s(j1,j2))/s(j1,j2)
    -0.5*L1(-t(j1,j2,j3),-s(j1,j2))/s(j1,j2)))
    -(3.0*delta(j5,j6,j3,j4,j1,j2)*zab2(j2,j3,j4,j1)
    *zab2(j5,j3,j4,j6)*zab2(j4,j1,j2,j3)
    /zab2(j3,j1,j2,j4)*std::pow(IDelta,2)
    +2.0*za(j3,j2)*zb(j2,j1)*zb(j4,j6)*(t(j1,j2,j3)-t(j1,j2,j4))
    *(za(j2,j5)*t(j1,j2,j3) + za(j2,j1)*zb(j1,j6)*za(j6,j5))
    /std::pow(zab2(j3,j1,j2,j4),3)*IDelta
    -(2.0*za(j2,j3)*zb(j3,j6)*(t(j1,j2,j3)-t(j1,j2,j4))
    +delta(j1,j2,j3,j4,j5,j6)
    *(za(j2,j5)*t(j1,j2,j3)
    +za(j2,j1)*zb(j1,j6)*za(j6,j5))/za(j5,j6))
    *za(j5,j2)*zb(j2,j1)/std::pow(zab2(j3,j1,j2,j4),2)*IDelta
    +0.5*(za(j1,j2)*std::pow(zb(j1,j6),2)/zb(j5,j6)
    +zb(j1,j2)*std::pow(za(j2,j5),2)/za(j5,j6)
    -2.0*za(j2,j5)*zb(j1,j6))*zab2(j4,j1,j2,j3)
    /zab2(j3,j1,j2,j4)*IDelta)
    *(lnrat(-s(j1,j2),-s(j3,j4)));
}

//---This is the whole expression in Eq.(11.6) subject to exchange flip_2
//---ie  flip2:( 1<-->2, 3<-->4, 5<-->6, za<-->zb)
static std::complex<double> Brackpm(int j1, int j2, int j3, int j4, int j5, int j6,
                                    FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  double IDelta;

  // statement functions
  auto t = [](int k1, int k2, int k3) { return s(k1,k2) + s(k2,k3) + s(k3,k1); };
  auto delta = [](int k1, int k2, int k3, int k4, int k5, int k6) { return s(k1,k2) - s(k3,k4) - s(k5,k6); };
  auto zab2 = [&za, &zb](int k1, int k2, int k3, int k4) { return za(k1,k2)*zb(k2,k4) + za(k1,k3)*zb(k3,k4); };

  IDelta = 1.0/(std::pow(s(j1,j2),2) + std::pow(s(j3,j4),2) + std::pow(s(j5,j6),2)
    -2.0*(+s(j1,j2)*s(j3,j4) + s(j1,j2)*s(j5,j6) + s(j5,j6)*s(j3,j4)));

  return
    -2.0*za(j2,j3)*zb(j4,j6)*zab2(j3,j1,j2,j6)
    *zab2(j2,j5,j6,j4)*t(j1,j2,j3)
    /za(j1,j2)/zb(j5,j6)/std::pow(zab2(j3,j1,j2,j4),4)
    *Lsm1_2mh(s(j3,j4),t(j1,j2,j3),s(j1,j2),s(j5,j6))
    +(2.0*za(j2,j3)*zb(j4,j6)
    *(zb(j1,j2)*za(j5,j6)*za(j2,j3)*zb(j4,j6)
    -zab2(j5,j2,j4,j1)*zab2(j3,j1,j2,j4))*zab2(j4,j1,j2,j3)
    *(t(j1,j2,j3)-t(j1,j2,j4))/std::pow(zab2(j3,j1,j2,j4),3)*IDelta
    -3.0*(s(j3,j4)*delta(j3,j4,j1,j2,j5,j6)*zab2(j2,j3,j4,j1)
     *zab2(j5,j3,j4,j6)*IDelta
    -za(j2,j3)*zb(j3,j1)*za(j5,j4)*zb(j4,j6)
    -za(j2,j4)*zb(j4,j1)*za(j5,j3)*zb(j3,j6))
    *zab2(j4,j1,j2,j3)/zab2(j3,j1,j2,j4)*IDelta
    -zb(j1,j4)*za(j3,j5)*za(j2,j3)*zb(j4,j6)
    *std::pow(zab2(j4,j1,j2,j3),2)/std::pow(zab2(j3,j1,j2,j4),2)*IDelta
    -zb(j1,j3)*za(j4,j5)*za(j2,j4)*zb(j3,j6)*IDelta)
    *i3m(s(j1,j2),s(j3,j4),s(j5,j6))
    +(2.0*za(j2,j3)*zb(j4,j6)*t(j1,j2,j3)*zab2(j2,j1,j4,j6)
    /za(j1,j2)/zb(j5,j6)/std::pow(zab2(j3,j1,j2,j4),3)
    -(std::pow(zab2(j2,j1,j4,j6),2)
     +2.0*za(j2,j3)*zb(j3,j6)*za(j2,j4)*zb(j4,j6))
    /za(j1,j2)/zb(j5,j6)/std::pow(zab2(j3,j1,j2,j4),2))
    *lnrat(-t(j1,j2,j3),-s(j3,j4))
    //---ie  flip3:( 1<-->5, 2<-->6, 3<-->4, za<-->zb)
    +Brackpma(j1,j2,j3,j4,j5,j6,za,zb)
    +Brackpma(j5,j6,j4,j3,j1,j2,zb,za)
    +zb(j1,j6)*zab2(j4,j1,j2,j3)
    *(zb(j1,j6)*delta(j3,j4,j5,j6,j1,j2)
    -2.0*zb(j1,j2)*za(j2,j5)*zb(j5,j6))
    /zb(j1,j2)/zb(j5,j6)/zab2(j3,j1,j2,j4)*IDelta
    +(std::pow(zab2(j2,j1,j4,j6),2) + za(j2,j1)*zb(j1,j6)*za(j2,j5)*zb(j5,j6))
    /za(j1,j2)/zb(j5,j6)/std::pow(zab2(j3,j1,j2,j4),2);
}

//--- This function returns the result of BDK
//--- Published in Nucl.Phys.B513:3-86,1998.
//--- e-Print: hep-ph/9708239
//--- Eqs.(11.1) and Eqs.(11.6) as appropriate dependent on choice of "st"
std::complex<double> Fvs(int st, int j1, int j2, int j3, int j4, int j5, int j6,
                         FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  std::complex<double> Fvs_res(0.0, 0.0);

  // statement functions
  auto t = [](int k1, int k2, int k3) { return s(k1,k2) + s(k2,k3) + s(k3,k1); };

  //---This is the square bracket in Eq.(11.1) subject to exchange 16,25
  auto Brackppa = [&za, &zb, &t](int k1, int k2, int k3, int k4, int k5, int k6) {
    return
      za(k1,k2)*std::pow(za(k5,k3)*zb(k3,k1),2)/za(k5,k6)/std::pow(za(k3,k4),2)
      *L1(-t(k1,k2,k3),-s(k1,k2))/std::pow(s(k1,k2),2)
      +za(k5,k2)*za(k5,k3)*zb(k3,k1)/za(k5,k6)/std::pow(za(k3,k4),2)
      *L0(-t(k1,k2,k3),-s(k1,k2))/s(k1,k2);
  };

  //---This is the whole expression in Eq.(11.1) subject to exchange 34
  auto Brackpp = [&za, &zb, &t, &Brackppa](int k1, int k2, int k3, int k4, int k5, int k6) {
    return
      -za(k2,k3)*za(k2,k4)*za(k3,k5)*za(k4,k5)
      /za(k1,k2)/za(k5,k6)/std::pow(za(k3,k4),4)
      *Lsm1_2me(t(k1,k2,k3),t(k1,k2,k4),s(k1,k2),s(k5,k6))
      -(za(k2,k4)*za(k3,k5) + za(k2,k3)*za(k4,k5))
      /za(k1,k2)/za(k5,k6)/std::pow(za(k3,k4),3)
      *(za(k5,k3)*zb(k3,k1)*za(k1,k2)
      *L0(-t(k1,k2,k3),-s(k1,k2))/s(k1,k2)
      +za(k5,k6)*zb(k6,k4)*za(k4,k2)
      *L0(-t(k1,k2,k3),-s(k5,k6))/s(k5,k6)
      +0.5*za(k5,k2)*(lnrat(-t(k1,k2,k3),-t(k1,k2,k4))))
      -Brackppa(k1,k2,k3,k4,k5,k6)-Brackppa(k6,k5,k3,k4,k2,k1)
      +0.5/std::pow(za(k3,k4),2)
      *(std::pow(za(k2,k5),2)/za(k1,k2)/za(k5,k6)
      -std::pow(zb(k1,k6),2)/zb(k1,k2)/zb(k5,k6));
  };
  // end statement functions

  if (st == hqpqbmgpgm) {
    //---flip2:( 1<-->2, 3<-->4, 5<-->6, za<-->zb)
    Fvs_res =
      +Brackpm(j1,j2,j3,j4,j5,j6,za,zb)
      +Brackpm(j2,j1,j4,j3,j6,j5,zb,za);
  } else if (st == hqpqbmgpgp) {
    //---exch34:(3<-->4)
    Fvs_res =
      +Brackpp(j1,j2,j3,j4,j5,j6)
      +Brackpp(j1,j2,j4,j3,j5,j6);
  }

  return Fvs_res;
}

extern "C" {
  std::complex<double> Fvs_wrapper(int st, int j1, int j2, int j3, int j4, int j5, int j6,
                                   std::complex<double>* fza, std::complex<double>* fzb) {

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    std::complex<double> Fvs_out;
    Fvs_out = Fvs(st, j1, j2, j3, j4, j5, j6, za, zb);   // @coverage-probe
    return Fvs_out;
  }
}
