#include <W1jet.hpp>

using namespace mxpart_mod;

//     Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
//     Eq.10.18
std::complex<double> FFPMccTtilde(int j1, int j2, int j3, int j4, int j5, int j6,
                                  FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  //     Statement functions
  auto zab2 = [&za, &zb](int k1, int k2, int k3, int k4) { return za(k1,k2)*zb(k2,k4) + za(k1,k3)*zb(k3,k4); };
  auto zab = [&za, &zb](int k1, int k2, int k3) { return za(k1,k2)*zb(k2,k3); };
  //     End statement functions

  return 1.0/(zab2(j1,j2,j3,j4)*zab2(j3,j1,j4,j2))
    *(0.5*(zab(j4,j1,j3)-zab(j4,j2,j3))*zab2(j5,j1,j4,j6)
