std::complex<double> FFPMscT(int j1, int j2, int j3, int j4, int j5, int j6,
                             FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  double Delta3, delta12, delta56;

  //     Statement functions
  auto zab2 = [&za, &zb](int k1, int k2, int k3, int k4) { return za(k1,k2)*zb(k2,k4) + za(k1,k3)*zb(k3,k4); };
  auto zab = [&za, &zb](int k1, int k2, int k3) { return za(k1,k2)*zb(k2,k3); };
  auto zba = [&za, &zb](int k1, int k2, int k3) { return zb(k1,k2)*za(k2,k3); };
  auto zb22b = [&za, &zb, &zab2](int k1, int k2, int k3, int k4, int k5, int k6) {
    return zb(k1,k2)*zab2(k2,k4,k5,k6) + zb(k1,k3)*zab2(k3,k4,k5,k6);
  };
  //     End statement functions

  Delta3 = std::pow(s(j1,j2),2) + std::pow(s(j3,j4),2) + std::pow(s(j5,j6),2)
    -2.0*s(j1,j2)*s(j3,j4) - 2.0*s(j3,j4)*s(j5,j6) - 2.0*s(j5,j6)*s(j1,j2);
  delta12 = s(j1,j2) - s(j3,j4) - s(j5,j6);
  delta56 = s(j5,j6) - s(j1,j2) - s(j3,j4);

